// Retain the known mappings on existing samples; new queries require explicit selections.
fields.forEach(f=>{f.dateColumn??='date';f.entityIdColumn??='entity_id'});
const rawPopulateColumns=populateRegistryColumns;
populateRegistryColumns=function(){const cols=rawPopulateColumns();const d=registryQueryDraft;for(const c of cols){if(c.column===d.dateColumn){c.dataType='Date';c.kind='Date';c.role='Required'}else if(c.column===d.entityIdColumn)c.role='Required';else if(c.role==='Required')c.role='Ignore'}return cols};
function registryColumnMappings(){const d=registryQueryDraft;return `<div class="grid" style="margin-top:22px"><div class="group"><label class="label" for="registryDateColumn">Date column ${info('Choose the query output used to place activity in the evaluation period. Set its data type to Date.')}</label><select id="registryDateColumn"><option value="">Select date column</option>${d.columns.filter(c=>c.dataType==='Date').map(c=>`<option value="${c.column}" ${c.column===d.dateColumn?'selected':''}>${esc(c.column)}</option>`).join('')}</select></div><div class="group"><label class="label" for="registryEntityColumn">Entity ID column ${info('Choose the identifier of the entity being evaluated. Other ID columns are not assumed to identify the payee.')}</label><select id="registryEntityColumn"><option value="">Select entity ID column</option>${d.columns.filter(c=>c.dataType!=='Date').map(c=>`<option value="${c.column}" ${c.column===d.entityIdColumn?'selected':''}>${esc(c.column)}</option>`).join('')}</select></div></div>`}
function bindRegistryColumnMappings(){for(const [id,key] of [['registryDateColumn','dateColumn'],['registryEntityColumn','entityIdColumn']])document.getElementById(id)?.addEventListener('change',e=>{const d=registryQueryDraft;d[key]=e.target.value;d.columns.forEach(c=>{if(c.role==='Required')c.role='Ignore';if([d.dateColumn,d.entityIdColumn].includes(c.column)){c.role='Required';if(d.primary===c.column)d.primary=''}});renderRegistryQuery()})}
const baseEntityTable=detectedEntityTable;
detectedEntityTable=function(){const m=mappingDraft;let html=baseEntityTable();html=html.replace(/<th>ENTITY ID[\s\S]*?<\/th>/,'');html=html.replace(/<td><input type="radio"[\s\S]*?<\/td>/g,'');return `<div class="grid" style="margin:18px 0"><div class="group"><label class="label" for="entityIdColumnSelect">Entity ID column</label><select id="entityIdColumnSelect"><option value="">Select entity ID column</option>${m.parameters.filter(p=>p.type!=='Date').map(p=>`<option value="${p.column}" ${p.identity?'selected':''}>${esc(p.column)}</option>`).join('')}</select></div></div>`+html};
const mappedBindings=bindMappings;
bindMappings=function(){mappedBindings();document.getElementById('entityIdColumnSelect')?.addEventListener('change',e=>{mappingDraft.parameters.forEach(p=>{p.identity=p.column===e.target.value;if(p.identity)p.included=true});render()});document.querySelectorAll('[data-entity-type]').forEach(el=>el.onchange=()=>{const p=mappingDraft.parameters[Number(el.dataset.entityType)];p.type=el.value;if(p.type==='Date'&&p.identity)p.identity=false;if(p.type!=='Date'&&p.column===mappingDraft.dateColumn)mappingDraft.dateColumn='';render()})};
const columnEntityValidation=validateEntityQuery;
validateEntityQuery=function(m){const error=columnEntityValidation(m);if(error)return error;return ''};
const noSourceEditor=mappingEditor;
mappingEditor=function(){return noSourceEditor().replace(/<span class="badge">(?:HRMS, FAAS|Vendor DB)<\/span>/g,'').replace(/<div class="group"><span class="eyebrow">SOURCE<\/span>[\s\S]*?<\/div>/g,'')};
const noSourceList=mappingList;
mappingList=function(){return noSourceList().replace('<th>SOURCE</th>','').replace(/<td>(?:HRMS, FAAS|Vendor DB)<\/td>/g,'').replace('Business Line ↔ Entity ↔ Data','Business Line ↔ Entity ↔ Query')};
const noSourceContext=context;
context=function(){return noSourceContext().replace(/<div><span class="eyebrow">SOURCE<\/span>[\s\S]*?<\/div>/g,'')};
render();
